package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.normalizeAngle.
 * This method normalizes an angle 'a' such that it lies within the range [center - PI, center + PI).
 */
public class MathUtils_normalizeAngle_TriageGen2Test {

    private static final double DELTA = 1e-12;
    private static final double PI = Math.PI;
    private static final double TWO_PI = 2.0 * Math.PI;

    @Test
    public void testNormalizeAngle_StandardRange() {
        // If 'a' is already within [center-PI, center+PI), it should return 'a'
        double center = 0.0;
        assertEquals(0.5, MathUtils.normalizeAngle(0.5, center), DELTA);
        assertEquals(-0.5, MathUtils.normalizeAngle(-0.5, center), DELTA);
        assertEquals(PI - 0.0001, MathUtils.normalizeAngle(PI - 0.0001, center), DELTA);
        assertEquals(-PI + 0.0001, MathUtils.normalizeAngle(-PI + 0.0001, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_PositiveOverflow() {
        // Test values larger than center + PI
        double center = 0.0;
        // 2*PI + 0.5 should normalize to 0.5
        assertEquals(0.5, MathUtils.normalizeAngle(TWO_PI + 0.5, center), DELTA);
        // 4*PI - 0.5 should normalize to -0.5
        assertEquals(-0.5, MathUtils.normalizeAngle(4.0 * PI - 0.5, center), DELTA);
        // Exactly PI should wrap to -PI (depending on floor behavior, but usually center-PI)
        // Formula: a - 2PI * floor((a + PI - 0)/2PI)
        // a = PI: PI - 2PI * floor(2PI/2PI) = PI - 2PI = -PI
        assertEquals(-PI, MathUtils.normalizeAngle(PI, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_NegativeOverflow() {
        // Test values smaller than center - PI
        double center = 0.0;
        // -2*PI + 0.5 should normalize to 0.5
        assertEquals(0.5, MathUtils.normalizeAngle(-TWO_PI + 0.5, center), DELTA);
        // -4*PI + 1.0 should normalize to 1.0
        assertEquals(1.0, MathUtils.normalizeAngle(-4.0 * PI + 1.0, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_WithOffsetCenter() {
        // Test with a non-zero center
        double center = PI; 
        // Range is [0, 2PI)
        // a = 0.5 -> 0.5
        assertEquals(0.5, MathUtils.normalizeAngle(0.5, center), DELTA);
        // a = 2PI + 0.5 -> 0.5
        assertEquals(0.5, MathUtils.normalizeAngle(TWO_PI + 0.5, center), DELTA);
        // a = -0.5 -> 2PI - 0.5 in the [0, 2PI) range? 
        // Let's check formula: -0.5 - 2PI * floor((-0.5 + PI - PI)/2PI) = -0.5 - 2PI * floor(-0.25/2PI)
        // floor(-0.039) = -1. Result: -0.5 - 2PI*(-1) = 2PI - 0.5
        assertEquals(TWO_PI - 0.5, MathUtils.normalizeAngle(-0.5, center), DELTA);
    }

    @Test
    public void testNormalizeAngle_LargeValues() {
        double center = 0.0;
        // Very large number to check stability
        double largeA = 1000000.0 * TWO_PI + 1.0;
        double normalized = MathUtils.normalizeAngle(largeA, center);
        // The result should be within [-PI, PI)
        assert(normalized >= -PI && normalized < PI);
        assertEquals(1.0, normalized, 1e-7); // Precision might degrade slightly with extremely large doubles
    }

    @Test
    public void testNormalizeAngle_ZeroAndEdgeCases() {
        double center = 0.0;
        assertEquals(0.0, MathUtils.normalizeAngle(0.0, center), DELTA);
        assertEquals(0.0, MathUtils.normalizeAngle(TWO_PI, center), DELTA);
        assertEquals(0.0, MathUtils.normalizeAngle(-TWO_PI, center), DELTA);
    }
}
